{
  "decision-allocate-refurbishment-kits-to-warranty-lots": "WITH plans(plan_code, jobs, kits_used, savings) AS (SELECT '', 0, 0, 0 UNION ALL SELECT lot_code, 1, kits_needed, replace_cents - refurb_cents FROM return_lot UNION ALL SELECT a.lot_code || ',' || b.lot_code, 2, a.kits_needed + b.kits_needed, (a.replace_cents - a.refurb_cents) + (b.replace_cents - b.refurb_cents) FROM return_lot AS a JOIN return_lot AS b ON a.lot_code COLLATE BINARY < b.lot_code) SELECT plan_code, kits_used, (SELECT COALESCE(SUM(replace_cents), 0) FROM return_lot) - savings AS provision_cents FROM plans CROSS JOIN shop_limit WHERE kits_used <= kit_stock ORDER BY provision_cents, jobs, plan_code COLLATE BINARY LIMIT 1",
  "decision-allocate-renewal-deposit-budget": "SELECT e.quote_id AS east_quote, w.quote_id AS west_quote, e.annual_cents AS east_premium_cents, w.annual_cents AS west_premium_cents, e.deposit_cents + w.deposit_cents AS total_deposit_cents, e.retained_cents + w.retained_cents AS total_retained_cents FROM renewal_quote AS e CROSS JOIN renewal_quote AS w CROSS JOIN treasury_limit AS t WHERE e.pool_code = 'EAST' AND w.pool_code = 'WEST' AND e.deposit_cents + w.deposit_cents <= t.cash_cap AND e.retained_cents + w.retained_cents <= t.risk_cap ORDER BY e.annual_cents + w.annual_cents, total_deposit_cents, e.quote_id COLLATE BINARY, w.quote_id COLLATE BINARY LIMIT 1",
  "decision-allocate-two-relay-legs": "SELECT o.runner_code AS opening_runner, c.runner_code AS closing_runner, o.trial_seconds + c.trial_seconds AS total_seconds, o.drill_slots + c.drill_slots AS slots_used FROM leg_trials AS o JOIN leg_trials AS c ON o.runner_code COLLATE BINARY <> c.runner_code WHERE o.leg_code = 'open' AND c.leg_code = 'close' AND o.drill_slots + c.drill_slots <= 6 ORDER BY total_seconds, slots_used, o.runner_code COLLATE BINARY, c.runner_code COLLATE BINARY LIMIT 1",
  "decision-allocate-two-reminder-slots": "WITH pairs AS (SELECT a.session_code AS first_code, b.session_code AS second_code, a.crew_minutes + b.crew_minutes AS crew_minutes FROM sessions AS a JOIN sessions AS b ON a.session_code COLLATE BINARY < b.session_code WHERE a.crew_minutes + b.crew_minutes <= 10), reached AS (SELECT DISTINCT p.first_code, p.second_code, r.batch_code, r.return_count FROM pairs AS p JOIN batch_reach AS r ON r.session_code IN (p.first_code, p.second_code)) SELECT p.first_code, p.second_code, COALESCE(SUM(r.return_count), 0) AS recovered_count, p.crew_minutes FROM pairs AS p LEFT JOIN reached AS r ON r.first_code = p.first_code AND r.second_code = p.second_code GROUP BY p.first_code, p.second_code, p.crew_minutes ORDER BY recovered_count DESC, p.crew_minutes, p.first_code COLLATE BINARY, p.second_code COLLATE BINARY LIMIT 1"
}
